+function start(){if(scene==='title'||scene==='dead'||scene==='won'){eyebrow.textContent='A blade against the dark';titleEl.innerHTML='The Hollow<br>March';introEl.textContent='The old road has gone quiet. Gather the three sun-relics, cut through the hollowbound, and light the beacon beyond the pass.';document.querySelector('.objective').innerHTML='<span>✧</span><span>Find <b>3 sun-relics</b> and defeat the hollowbound to open the pass.</span>';document.querySelector('.key-note').innerHTML='A / D or ← / → to move<br>SPACE to jump · J to attack';startBtn.innerHTML='Begin the march&nbsp; →';reset();scene='playing';overlay.classList.add('hidden');hint.style.opacity='1';startBtn.blur();playTone(360,.08)}}
 startBtn.addEventListener('click',start);
 function endScreen(win){scene=win?'won':'dead';overlay.classList.remove('hidden');eyebrow.textContent=win?'The beacon remembers':'The road claims another';titleEl.innerHTML=win?'A light<br>returned':'Fall, then<br>rise again';introEl.textContent=win?'The pass is clear. The first dawn in a hundred years spills over the Hollow March.':'The hollowbound still haunt the road, but your story is not over. Take a breath and try again.';startBtn.innerHTML=win?'Walk the road again&nbsp; →':'Rise again&nbsp; →';document.querySelector('.objective').innerHTML=win?'<span>✧</span><span>You collected <b>'+relics.filter(r=>!r.on).length+' relics</b> and defeated <b>'+enemies.filter(e=>!e.alive).length+' foes</b>.</span>':'<span>✧</span><span>Keep moving, time your strikes, and watch for the <b>sun-relics</b>.</span>';document.querySelector('.key-note').innerHTML='A / D move · SPACE jump<br>J to strike';}
 function playTone(freq,dur=.08){if(muted)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type='triangle';o.frequency.value=freq;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch(e){}}
 document.getElementById('soundBtn').addEventListener('click',e=>{muted=!muted;e.currentTarget.textContent=muted?'♫':'♪';if(!muted)playTone(540,.1)});
